INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('e16ca455-7a34-4d8f-96e9-05eab45e61a4', '21feff02-016d-46e2-bb9d-c27495133b1b', '121. óra: Kördiagram', 'Kördiagram értelmezése, körcikkek szöge, százalékos megoszlás.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "e3f12f64-1a68-4f06-8dd7-0efa01a09970", "text": "Mire szolgál a kördiagram?", "type": "multiple-choice", "options": [{"id": "04c3316a-5ce7-4dce-8814-6811f05ca4c9", "text": "Az egyes részek teljes egészhez (100%) viszonyított arányának szemléltetésére", "isCorrect": true}, {"id": "7e980db1-e133-4aa5-a3d2-6033a9e2b61f", "text": "Vonalak összekötésére", "isCorrect": false}, {"id": "a152b545-f36d-46a6-8ca8-4244179236aa", "text": "Pontok rajzolására", "isCorrect": false}, {"id": "8215b057-8e4e-4189-9cb9-6ad427055237", "text": "Időbeli növekedés ábrázolására", "isCorrect": false}], "timeLimit": 15}, {"id": "6d76efd9-5b1a-4442-9901-bafde193ba83", "text": "Hány fokos a kördiagram teljes köre (100%)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "47d25592-d39b-4023-a262-3cf99f420e2c", "text": "Hány fokos körcikk tartozik az 50%-os (fél) részhez? (360 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "2309d380-6200-47ef-9084-33c07ae5213c", "text": "Hány fokos körcikk tartozik a 25%-os (negyed) részhez? (360 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "8401e336-0f06-40cf-8ce5-56bc87ffd617", "text": "Hány fokos körcikk tartozik a 10%-os részhez? (360 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "ed2427c2-9b34-4405-b846-25a92e37ef6b", "text": "A kördiagramon a körcikkek középponti szögei egyenesen arányosak a képviselt százalékkal.", "type": "true-false", "options": [{"id": "85838e44-613e-4e67-a33d-82563932551f", "text": "Igaz", "isCorrect": true}, {"id": "aa95e491-44c1-4de2-965c-3e411bbd3c3e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e1720b7a-17a8-44bc-8b02-de3c62b3d10e", "text": "A körcikkek szögeinek összege mindig 360°.", "type": "true-false", "options": [{"id": "1000afab-e737-4f8d-88f0-a4d5b5bfe179", "text": "Igaz", "isCorrect": true}, {"id": "f5f5a0b2-fa23-4856-b6e1-13c455dbd820", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('4fc54901-3569-4677-a4f9-e847eb32c051', '21feff02-016d-46e2-bb9d-c27495133b1b', '122. óra: Adatok ábrázolása, átlag', 'Számtani közép (átlag) kiszámítása és ábrázolás digitális eszközzel.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "b2fbe511-d70e-4c48-8c3c-d862f8eeafd7", "text": "Hogyan számítjuk ki több szám számtani középértékét (átlagát)?", "type": "multiple-choice", "options": [{"id": "c29731e6-dbaa-4dc4-b002-aae6b5ebfd94", "text": "Összeadjuk az adatokat, majd az összeget elosztjuk az adatok darabszámával", "isCorrect": true}, {"id": "751f2ac2-55b2-4ff1-aa66-19e4ecf319d4", "text": "Megszorozzuk az adatokat", "isCorrect": false}, {"id": "26021e8e-36f9-48e0-9d2b-4d3996feb48e", "text": "Kivonjuk a legkisebbet a legnagyobból", "isCorrect": false}, {"id": "151a05aa-4e2b-49c8-98e7-c13e81ebbac9", "text": "Kiválasztjuk a leggyakoribb számot", "isCorrect": false}], "timeLimit": 15}, {"id": "8df75fb1-5177-44d4-8c30-0629c36cabf7", "text": "Mennyi a 4, 6, 8, 10 számok átlaga? (28 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "d61551d8-2547-4553-b849-701bdd0ae32e", "text": "Mennyi a 10, 20, 30, 40, 50 számok átlaga? (150 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "05b3c82d-4ee8-4aa2-8e29-213cfac73ac8", "text": "Egy diák osztályzatai: 5, 4, 5, 5, 3. Mennyi a tanulmányi átlaga? (22 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.4"}, {"id": "4471b358-21a3-4142-9b68-c59e27865e00", "text": "Az átlag értéke mindig a legkisebb és a legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "eee76bf0-3ad0-4094-832a-c3e32be9db6a", "text": "Igaz", "isCorrect": true}, {"id": "5dfc0a17-d280-4aa9-98aa-d8ddf917b053", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "41f16ab3-5873-44aa-bc67-967e4ced3f4b", "text": "Digitális táblázatkezelőben (pl. Excel) az ÁTLAG (AVERAGE) függvény azonnal kiszámolja az átlagot.", "type": "true-false", "options": [{"id": "f98a81ad-30c5-4fcd-b195-908aa9d964a6", "text": "Igaz", "isCorrect": true}, {"id": "668873f5-c1bd-4a8d-a505-999f08de6ec7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bb9316bc-bf54-445b-9ff7-dcd11b92f9db", "text": "Mennyi a 15 és 25 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()),
('6aa0b325-ce5b-48db-876a-d6dc568e6493', '21feff02-016d-46e2-bb9d-c27495133b1b', '123. óra: Dobáljunk kockákat!', 'Kísérletezés dobókockával, gyakoriság, relatív gyakoriság és valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "a0fb56cd-10ba-4f1c-ba5d-3b78f4df14a0", "text": "Egy szabályos 6 oldalú dobókockával mekkora az esélye a 6-os dobásnak?", "type": "multiple-choice", "options": [{"id": "75ea4c98-600b-45d3-bd21-0b1128097352", "text": "1 a 6-ból (1/6)", "isCorrect": true}, {"id": "e352deff-0e28-47ad-8f44-1467a61481ca", "text": "1 a 2-ből", "isCorrect": false}, {"id": "47dc7a17-1db9-4753-99a1-09d7d5bf70c2", "text": "100%", "isCorrect": false}, {"id": "46141411-89f7-4db2-955a-7d997dcc5fac", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "3e664ed3-7809-49cb-9696-9993665d73ee", "text": "Mennyi a páros szám (2, 4, 6) dobásának valószínűsége dobókockával?", "type": "multiple-choice", "options": [{"id": "cb0cbbe3-1e8b-41ab-9ec1-e9d6356bc84f", "text": "3 a 6-ból (3/6 = 1/2 azaz 50%)", "isCorrect": true}, {"id": "19ec53a5-6985-4701-897f-c5ace61d6018", "text": "1/6", "isCorrect": false}, {"id": "3ccd5b4d-c416-46fe-ace4-f81970dc8d68", "text": "2/6", "isCorrect": false}, {"id": "49be73a0-6cf6-4335-bdf7-745c4d3c0933", "text": "100%", "isCorrect": false}], "timeLimit": 15}, {"id": "39a9ab41-bbf3-48b2-96f6-80271d93a05e", "text": "Sok dobási kísérlet végrehajtásakor a relatív gyakoriság megközelíti az elméleti valószínűséget.", "type": "true-false", "options": [{"id": "f8d55bde-6d5a-4fb4-8845-dab6fc5e5f41", "text": "Igaz", "isCorrect": true}, {"id": "d423af42-fd7c-4b4a-9352-751f523facb1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7df10768-85b2-4f50-8255-e5b052580094", "text": "Milyen esemény egy kockával 7-est dobni?", "type": "multiple-choice", "options": [{"id": "da5fe61c-b18a-4d5d-9ebe-ba648f23c136", "text": "Lehetetlen esemény (0%)", "isCorrect": true}, {"id": "945a0d33-c376-4a1d-84f8-c3bb20159c95", "text": "Biztos esemény", "isCorrect": false}, {"id": "3de731fd-83d5-40af-a3c0-c96a118ddd17", "text": "Lehetséges", "isCorrect": false}, {"id": "0f5a37d8-e654-4a27-9a84-089013d7ea7d", "text": "Véletlen", "isCorrect": false}], "timeLimit": 15}, {"id": "f445cf52-6610-41f6-9780-0a3ec2d53528", "text": "Milyen esemény egy kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "9425dd5d-d18f-45bb-92a3-eaef74753bfc", "text": "Biztos esemény (100%)", "isCorrect": true}, {"id": "e38bbfdf-b5e7-45ab-946c-15e09089194e", "text": "Lehetetlen", "isCorrect": false}, {"id": "d894be0d-f7c6-464c-9a20-4e308843d33c", "text": "Kétes", "isCorrect": false}, {"id": "158374f5-2086-45cf-b162-c109a2b0e35b", "text": "Ritka", "isCorrect": false}], "timeLimit": 15}, {"id": "0997d13f-1a6c-4800-986f-fcbd884a19e2", "text": "Hányféle kimenetele lehet két kocka dobásakor a kapott összegeknek? (2-től 12-ig: 11-féle)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "7f7fd9a1-bbd5-4df9-8c93-6280db1ed789", "text": "Két kockával a leggyakoribb dobási összeg a 7.", "type": "true-false", "options": [{"id": "ab02db17-7ee9-47ec-8a9c-9ba46bde6f7e", "text": "Igaz", "isCorrect": true}, {"id": "0b88507d-e804-4dd3-b65c-90dbcb6a9c4a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('b40879bd-0845-4060-bb80-01a697a52a44', '21feff02-016d-46e2-bb9d-c27495133b1b', '124. óra: Dobáljunk pénzérmét!', 'Kísérletezés érmével, fej vagy írás, tapasztalati valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "cad4bff5-6413-465b-acab-cc1655945919", "text": "Egy szabályos pénzérme feldobásakor mekkora a fej dobás valószínűsége?", "type": "multiple-choice", "options": [{"id": "fa8cc8b0-9652-4939-b60b-5a6927c34b20", "text": "1 a 2-ből (1/2 azaz 50%)", "isCorrect": true}, {"id": "bfacb7ed-2bb7-4ba3-8bf1-edc2b241c19d", "text": "1/4", "isCorrect": false}, {"id": "c5e5b9c6-ca16-4728-b8ba-b6ae7411608c", "text": "100%", "isCorrect": false}, {"id": "57238ca0-4232-4767-97ec-70ac306c3884", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "aa50ee9d-8a6e-4fbb-835a-be21bf970583", "text": "Ha 100-szor dobunk fel egy érmét, a fej dobások száma kb. 50 körül várható.", "type": "true-false", "options": [{"id": "6b339530-6d8b-4ee4-8f67-3a50f7237b63", "text": "Igaz", "isCorrect": true}, {"id": "eb1be8c3-2463-48b8-adb9-2b90133cbe4f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a25efa42-e344-487e-9105-866358415d9e", "text": "Hány kimenetele lehet 2 érme egyidejű feldobásának? (FF, FI, IF, II)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "ae09729d-3e9b-4173-a160-7f0f14b48f26", "text": "Mekkora a valószínűsége annak, hogy 2 érmével mindkettő fej lesz? (1 a 4-ből = 25%)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "a6e0c1f8-4d5c-4fd0-8ec3-737225039b3b", "text": "A véletlen kísérletek eredményét az egyes próbálkozásoknál nem lehet pontosan kiszámítani, de nagy számnál szabályszerűség mutatkozik.", "type": "true-false", "options": [{"id": "a5fefcfe-26c2-49d5-b587-31fe8a66984e", "text": "Igaz", "isCorrect": true}, {"id": "7fb04f20-a0a9-4a2d-8fb3-b76a0c5b0574", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "292aa884-93e5-41de-9175-4a3d5a4952f9", "text": "A biztos esemény valószínűsége 100% (vagy 1).", "type": "true-false", "options": [{"id": "0effa53c-b066-40d0-82a7-4b8b014d774a", "text": "Igaz", "isCorrect": true}, {"id": "e6c71e37-bc00-49df-982f-4804ee1db3e4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cadf3a6c-b146-4498-b945-4cd282e5ddda", "text": "A lehetetlen esemény valószínűsége 0% (vagy 0).", "type": "true-false", "options": [{"id": "aefb8ae5-0a4b-4e39-a40a-c44b17dcfa24", "text": "Igaz", "isCorrect": true}, {"id": "eb87287a-0d4f-4c4e-91ee-c81d8991f2b5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('95f01655-bf9c-46cf-86d0-692ded5a34ef', '21feff02-016d-46e2-bb9d-c27495133b1b', '125. óra: Összefoglalás', 'Statisztikai és valószínűségi ismeretek összefoglalása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "ac3f269f-e858-4925-a596-2bbd3f5c306b", "text": "Mennyi a 6, 8, 10, 12 számok átlaga? (36 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "bd46a7f8-f2f9-47a4-8241-6def85658d33", "text": "Hány fokos körcikk felel meg a kördiagramon a 50%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "168a200f-4740-4946-88d4-d503c71ac2b6", "text": "Hány fokos körcikk felel meg a kördiagramon a 25%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "26c00b8e-282c-436b-86fc-0e400522ed23", "text": "Egy kockával 6-ost dobni 1/6 valószínűségű esemény.", "type": "true-false", "options": [{"id": "c96a58db-2731-4796-b93c-3fbc535dfe76", "text": "Igaz", "isCorrect": true}, {"id": "1a4b693c-6656-4b40-a8e3-d51bc6d287e9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2563ace4-6d83-45c1-a58f-456be03675e8", "text": "Az adatok átlagához az összes adat összegét elosztjuk a darabszámmal.", "type": "true-false", "options": [{"id": "2c235b7e-4fa4-4d64-89fe-b116ae142208", "text": "Igaz", "isCorrect": true}, {"id": "718324f9-1038-42c2-8d38-e2c8d2b9af08", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "63592854-5ea3-43e9-bbc9-f1259e02aa4e", "text": "Melyik grafikon alkalmas időbeli változás ábrázolására?", "type": "multiple-choice", "options": [{"id": "c36d0d30-834f-475b-b48a-bbb342e3b702", "text": "Vonaldiagram", "isCorrect": true}, {"id": "4440ce9a-3da2-4ebf-9199-1f2be2e79421", "text": "Kördiagram", "isCorrect": false}, {"id": "24d93170-a3ea-4a9c-b35f-a87ab33930ac", "text": "Pontdiagram", "isCorrect": false}, {"id": "a0cad472-3e78-43ff-850f-f7a29c672b43", "text": "Képrejtvény", "isCorrect": false}], "timeLimit": 15}, {"id": "9d19b3a7-acdf-4924-9a58-c060c9390033", "text": "Mennyi a 20 és 40 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()),
('dcbadd04-7a16-45e8-85b8-948277b0b985', '21feff02-016d-46e2-bb9d-c27495133b1b', '126. óra: Számonkérés', 'Számonkérés projektmunka és teszt formájában a Statisztikából (10 kérdés).', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "e9eed3f3-fc8a-4fd6-b68c-22de4e92b02a", "text": "1. Mennyi a 10, 20, 30 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "13e0a808-5cac-4fbe-be9b-c33de9f35d15", "text": "2. Mennyi a 2, 4, 6, 8, 10 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "576aaaec-fd9c-4550-931b-1be927fab61a", "text": "3. Hány fokos a teljes kör a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "ada77b96-84d5-4f07-bb86-506ef626e4d3", "text": "4. Hány fokos körcikk jelöli a 10%-ot a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "f8665607-a20c-4ed7-8642-0724e978097c", "text": "5. Mekkora a fej dobás valószínűsége százalékban egy szabályos érmével?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "11e022b5-8313-407b-8d43-61a69e775c6d", "text": "6. Milyen esemény egy 6 oldalú kockával 8-ast dobni?", "type": "multiple-choice", "options": [{"id": "ac844779-9b9a-457c-bc9f-4888c8085e31", "text": "Lehetetlen esemény", "isCorrect": true}, {"id": "2f11dd2a-28f1-4afe-9fde-a78c7df57809", "text": "Biztos esemény", "isCorrect": false}, {"id": "1c53cfc9-4e75-491d-a1e1-676b12ead279", "text": "Lehetséges", "isCorrect": false}, {"id": "dc06cb53-e98d-46d4-907a-3e79421e1b23", "text": "Döntetlen", "isCorrect": false}], "timeLimit": 15}, {"id": "b4a61a2c-545a-4e09-9196-98031c365a0e", "text": "7. Milyen esemény egy 6 oldalú kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "543de1cd-0d35-485d-adb4-1354fe19dc1d", "text": "Biztos esemény", "isCorrect": true}, {"id": "8eca495f-f3fc-48b9-bbe2-12df7c40c5b5", "text": "Lehetetlen esemény", "isCorrect": false}, {"id": "1263f252-3195-4ab1-97c0-32fcf0c2aed5", "text": "Ritka", "isCorrect": false}, {"id": "b4199999-5756-4832-b4d3-53e1989f4976", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1e5d0ec7-795a-4f47-9c2a-095192476942", "text": "8. Az adatok átlaga mindig a legkisebb és legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "59d9dc9a-0f3b-4080-b2a1-a7e9659a24b8", "text": "Igaz", "isCorrect": true}, {"id": "fb0eb3b0-0f26-4088-90f6-b058e1350faa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d7aafa27-05d6-4494-bc15-38895a7d1f1a", "text": "9. Hány kimenetele lehet 2 érme feldobásának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "3b518c90-d0eb-4435-89f7-3ca1b5b47938", "text": "10. A vonaldiagram az adatok időbeli alakulását mutatja meg jól.", "type": "true-false", "options": [{"id": "7d496e09-3bb7-4ef9-b346-c0495ae90916", "text": "Igaz", "isCorrect": true}, {"id": "4c858542-f736-46a2-a18c-8fa3c4b5fb38", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('61a7d87f-c716-4fb5-86d4-946d7b252696', '21feff02-016d-46e2-bb9d-c27495133b1b', '127. óra: A számonkérés értékelése', 'A statisztikai feladatok és projektmunkák megbeszélése, értékelése.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "675a0a84-d22c-47e3-b3c8-a3de4e0538bd", "text": "Mi volt a projektmunka és a számonkérés legfőbb tanulsága?", "type": "multiple-choice", "options": [{"id": "df9dbfa6-ea26-49e3-8fee-b973cd034e1e", "text": "Az adatok pontos rögzítése és a helyes skálázás elengedhetetlen a helyes diagramokhoz", "isCorrect": true}, {"id": "57a561e6-8396-4208-b5c4-6ce8fd6136be", "text": "A rajzolás nem fontos", "isCorrect": false}, {"id": "71b72103-2116-4c29-af86-c24f9228dfc8", "text": "A számolást el kell hagyni", "isCorrect": false}, {"id": "e6018d1f-6a84-494d-a0ab-ead9644c4ae0", "text": "Mindegy a skála", "isCorrect": false}], "timeLimit": 15}, {"id": "70a39769-1832-4305-a70b-a74b468bf361", "text": "Az átlag kiszámításánál a darabszámmal való osztást nem szabad elfelejteni.", "type": "true-false", "options": [{"id": "0f1153a0-baa2-4136-b74a-5ae718f235e0", "text": "Igaz", "isCorrect": true}, {"id": "28943792-ccbf-4766-8458-b16cbc1aabc7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "42c3cd7f-06b3-46a4-9f52-93174a97c389", "text": "Mennyi a 12 és 18 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "0d3ca9c0-fa0e-4b95-8076-49f96c64ada7", "text": "A kördiagram körcikkei összefüggenek a százalékos megoszlással.", "type": "true-false", "options": [{"id": "5e238732-0868-4669-9822-f6af20f83b8f", "text": "Igaz", "isCorrect": true}, {"id": "c1854537-ecff-4342-a163-632f7d6ae1b0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "76a743a0-1dab-49b7-bcbc-4a3c1ab77ba6", "text": "A kísérletek során nyert adatok segítenek megérteni a valószínűségi elveket.", "type": "true-false", "options": [{"id": "6f9d80a4-d63c-470b-8b45-4c2cc6b7e142", "text": "Igaz", "isCorrect": true}, {"id": "392b2c6b-5021-4dc1-952c-4ee6e21a6ae6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0d3f8634-06ab-47b2-8efa-fb4f3a762a7d", "text": "Mennyi a 5, 10, 15 átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "39a6d593-68c8-41a4-959d-50521ba6daec", "text": "A csoporteredmények bemutatása fejlesztette a kommunikációs készséget.", "type": "true-false", "options": [{"id": "9abf5739-1db3-4966-9515-31c6b9567aa2", "text": "Igaz", "isCorrect": true}, {"id": "6647577d-671c-440a-82f5-5805901c53a8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('e133b9c9-1bd1-4e34-bf83-e0fad62e41ed', '21feff02-016d-46e2-bb9d-c27495133b1b', '128. óra: Mindennapi pénzügyeink I.', 'Alapvető pénzügyi fogalmak: megtakarítás, kamat, kamatláb, futamidő, bankbetét.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "ee0ff85f-7538-46c5-951f-c3435744aec4", "text": "Mit jelent a banki megtakarítás (betét) után járó ''kamat''?", "type": "multiple-choice", "options": [{"id": "76f14fdc-41c3-4fb5-ad53-d4fad12250dc", "text": "A bank által a lekötött pénz használatáért fizetett plusz összeg", "isCorrect": true}, {"id": "7b43c186-db9e-4a9d-abc1-190f406979c9", "text": "A bankkezelési díj", "isCorrect": false}, {"id": "1e37826f-5ef5-45c0-9ae0-b84398df08ee", "text": "A büntetés", "isCorrect": false}, {"id": "4e0637da-7785-4b58-99bc-e66553a29b2f", "text": "A fizetett adó", "isCorrect": false}], "timeLimit": 15}, {"id": "a5213d2e-5fce-4c49-be1e-22964bef470e", "text": "Ha 100 000 Ft-ot beteszünk a bankba 5%-os éves kamatra, hány Ft kamatot kapunk 1 év múlva? (100000 * 0,05)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5000"}, {"id": "6ed17290-6ec7-4286-a6eb-f783cb5f5142", "text": "Mennyi pénzünk lesz a bankban az 1 év letelte után a 100 000 Ft betét és a 5000 Ft kamat összegeként?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "105000"}, {"id": "c5cc0648-dc03-422b-9930-9a25b08368ea", "text": "A futamidő az az időtartam, ameddig a pénzünket a bankban lekötjük.", "type": "true-false", "options": [{"id": "439b61d2-aa2d-4b1b-9887-82ef815a9fdf", "text": "Igaz", "isCorrect": true}, {"id": "e87f8201-315a-478e-906a-d9190c8c8c88", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "35a51d8e-77f2-41c6-8cc8-93ddf94b4c6d", "text": "A hitel felvételekor nekünk kell kamatot fizetnünk a banknak a kölcsönzött pénzért.", "type": "true-false", "options": [{"id": "6b6c2743-4569-48e0-9d3d-99de9d26c5b2", "text": "Igaz", "isCorrect": true}, {"id": "e7792468-cc48-4439-aa84-7ebb6dca47a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d5f0b878-4522-4265-b52d-b3a073c280da", "text": "A megtakarítás segít a váratlan kiadások fedezésében és jövőbeli célok megvalósításában.", "type": "true-false", "options": [{"id": "1346a9fb-f886-4899-a064-867bf2308880", "text": "Igaz", "isCorrect": true}, {"id": "b959c4ad-b8b1-4883-a6fd-18b7c879b531", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "43f3e474-4875-4ab0-8044-6c3fe9d63f05", "text": "Mennyi 200 000 Ft 10%-os éves kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}]'::jsonb, true, NOW()),
('5e6c9c6b-cd74-4f5a-a627-c38f3a7059e5', '21feff02-016d-46e2-bb9d-c27495133b1b', '129. óra: Mindennapi pénzügyeink II.', 'Devizák, valutavételi és -eladási árfolyam, valutaváltás.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "36e3b0d7-6090-4778-988b-0f065477ddd7", "text": "Mit jelent a valuta és deviza árfolyama?", "type": "multiple-choice", "options": [{"id": "37d7a2a5-e3d5-4cda-b9d3-5c7a32e59785", "text": "Egy külföldi pénznem (pl. Euró, Dollár) ára hazai pénzben (Ft-ban)", "isCorrect": true}, {"id": "50bee418-4204-4897-b2f3-b373173f59c4", "text": "A bankjegy színe", "isCorrect": false}, {"id": "d550cdf1-e416-46b8-80c5-71732a818e2b", "text": "A pénz súlya", "isCorrect": false}, {"id": "b5b88cf1-41df-4a5d-b8a0-b780954c949c", "text": "A bank nyitvatartása", "isCorrect": false}], "timeLimit": 15}, {"id": "dbc56b1c-a09e-4828-acc8-e41ee300363d", "text": "Ha 1 Euró (EUR) eladási árfolyama 400 Ft, hány Ft-ba kerül 50 Euró vásárlása? (50 * 400)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}, {"id": "c8a172ac-272d-40f2-abbe-3e349ee6fcf9", "text": "Ha 100 Eurót váltunk át Ft-ra 400 Ft/EUR vételi árfolyamon, hány Ft-ot kapunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40000"}, {"id": "c5696f6d-4784-4c20-b1ad-464390ba188a", "text": "A bankok eladási árfolyama magasabb, mint a vételi árfolyam (ebből származik a váltási haszon).", "type": "true-false", "options": [{"id": "0c64f27c-20a8-420a-be33-a205075b1439", "text": "Igaz", "isCorrect": true}, {"id": "f993a062-c565-4fb9-a823-7dc793a0b40f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b41e09a7-0164-4a01-b437-64b0c0faae0f", "text": "Melyik a közös európai pénznem jele és neve?", "type": "multiple-choice", "options": [{"id": "b02e4d76-a44f-4a45-b45b-a73176af9633", "text": "EUR (€) - Euró", "isCorrect": true}, {"id": "320a7b10-ca58-4af8-b977-0881c8a18ef9", "text": "USD ($) - Dollár", "isCorrect": false}, {"id": "9aec081f-0ada-467d-bdaa-439fa5a5c9e4", "text": "GBP (£) - Font", "isCorrect": false}, {"id": "f82267fa-cb3f-4581-8af3-c8156a02d39e", "text": "HUF (Ft) - Forint", "isCorrect": false}], "timeLimit": 15}, {"id": "bf3220ea-a35d-422f-b725-fea852aeba31", "text": "Külföldi utazás előtt érdemes tájékozódni a hivalatos árfolyamokról.", "type": "true-false", "options": [{"id": "1117750a-642e-41c0-b8a0-a6e7248a6ba7", "text": "Igaz", "isCorrect": true}, {"id": "8bf858f5-da95-4303-99de-02568b5df28b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "de72f7b9-caa2-4204-8fac-c8d11dd3d805", "text": "Hány Ft 10 Dollár (USD), ha 1 USD = 350 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}]'::jsonb, true, NOW()),
('3e705c6a-f5ba-4f65-a903-24b128779744', '21feff02-016d-46e2-bb9d-c27495133b1b', '130. óra: Az egész számokról tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: műveletek egész számokkal, előjelek, abszolút érték, ellentett.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "43a711fa-c73a-4d0c-bbd3-6ecc40f708b7", "text": "Mennyi (-15) + (+25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "0798bfd4-8fdd-4071-b27e-12ecec8c9076", "text": "Mennyi (-8) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "56"}, {"id": "e6fb3940-6f29-4f4d-8117-99c4228219eb", "text": "Mennyi (-63) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "db153530-68e0-4e5d-8fff-fe5492a4fd5f", "text": "Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "137c633b-088a-4010-ab6d-cb0076a3f775", "text": "Igaz", "isCorrect": true}, {"id": "bdaeb1e0-ab1d-4ad8-9f4e-d0f97086dacf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "53cbb652-d987-409c-8265-bafef83e8750", "text": "Mennyi |-40|?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "c81fc595-c7c2-4e96-82a3-c294b0966de8", "text": "Melyik szám nagyobb: -12 vagy -4?", "type": "multiple-choice", "options": [{"id": "3a22d308-4295-4fa1-9f1d-76ace5439055", "text": "-4", "isCorrect": true}, {"id": "6dfd1d3f-d253-491d-be3a-eeb53882fbf5", "text": "-12", "isCorrect": false}, {"id": "82f9e14e-1635-4373-8f35-dafc5ed6b9b9", "text": "Egyenlők", "isCorrect": false}, {"id": "d34f44f1-7bbd-48de-a103-9d5a76538f99", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}, {"id": "0afdc0f1-77e9-4aea-8b5c-26a77eb16d80", "text": "Mennyi (-5) * (-2) * (-3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;